async function processPayment(idempotencyKey, amount, accountId) {
  const existing = await db.findPaymentByKey(idempotencyKey)
  if (existing) {
    return existing.result   // already processed: return the original result
  }

  const result = await db.transaction(async (tx) => {
    await tx.debitAccount(accountId, amount)
    const payment = await tx.recordPayment(idempotencyKey, amount, accountId, 'success')
    return payment
  })

  return result
}

// Simplified flow of a payment authorization
async function authorizePayment(request) {
  const token = await tokenize(request.cardDetails)      // 1. immediate tokenization

  const routeDecision = router.selectNetwork(token, request.amount)  // 2. network selection

  const authResponse = await routeDecision.network.authorize({
    token,
    amount: request.amount,
    merchantId: request.merchantId,
  })                                                       // 3. bank authorization

  await auditLog.record(request.merchantId, authResponse.status)  // 4. traceability

  return authResponse.status === 'approved'
    ? { status: 'success', authCode: authResponse.code }
    : { status: 'declined', reason: authResponse.reason }
}

function computeRiskScore(transaction, accountHistory) {
  let score = 0

  const avgAmount = average(accountHistory.recentAmounts)
  if (transaction.amount > avgAmount * 5) score += 30      // unusual amount

  const lastLocation = accountHistory.lastTransactionLocation
  const distanceKm = geoDistance(lastLocation, transaction.location)
  const minutesSinceLast = minutesSince(accountHistory.lastTransactionTime)
  if (distanceKm > 500 && minutesSinceLast < 60) score += 50 // "impossible travel"

  if (accountHistory.recentDeclinedAttempts > 3) score += 20 // repeated failed attempts

  return score
}

function decide(score) {
  if (score >= 70) return 'block'
  if (score >= 30) return 'require_verification'  // e.g. SMS code
  return 'approve'
}
